pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _test(uint256 value) internal {
        value = bound(value, 0, 1000000000000000000000000000000);
        value = bound(value, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(value == 10);
        vm.assume(c.pot() == 0);
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        try c.play{value: value}() {} catch { return; }
        uint256 potAfterFirst;
        try c.pot() returns (uint256 __r) { potAfterFirst = __r; } catch { return; }
        vm.assume(potAfterFirst >= potBefore + value);
        try c.play{value: value}() {} catch { return; }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        assertTrue(potAfter >= potBefore + 20);
    }

    function testFuzz_test(uint256 value) public {
        _test(value);
    }

    receive() external payable {}
}
